	{
		System.Console.Out.WriteLine("F-428 P12.13 — auto-wrong census");
		System.Console.Out.WriteLine();
		System.Console.Out.WriteLine("usage:");
		System.Console.Out.WriteLine("  LetUsCook.AutoWrongCensus census <trace.jsonl>");
		System.Console.Out.WriteLine("      Classifies every auto-wrong line (auto == true && correct == false) of a");
		System.Console.Out.WriteLine("      debug or batch HoldoutGate trace by relation (accepted row vs key row) and");
		System.Console.Out.WriteLine("      site (reuse | override | curated | ranker). TSV on stdout, summary on stderr.");
		System.Console.Out.WriteLine();
		System.Console.Out.WriteLine("  LetUsCook.AutoWrongCensus pairs <census.tsv> <trace.jsonl>");
		System.Console.Out.WriteLine("      Emits the parsedName head and key head words for every census row whose");
		System.Console.Out.WriteLine("      blocker is 'window' and route is 'compound' or 'other'.");
		System.Console.Out.WriteLine();
		System.Console.Out.WriteLine("Exits 1 on a missing file, a trace whose set is not debug or batch, or a malformed invocation.");
	}
}
