{"content":"using System.Text.Json;

using LetUsCook.Fdc.Lexicon;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The key set of <c>Lexicon/Resources/exact-overrides.json</c> as shipped in the Fdc assembly —
/// the same embedded resource the production matcher loads, read here as data (no matcher logic).
/// </summary>
public sealed class ExactOverrideKeyIndex
{
	private readonly FrozenSet<string> _keys;

	private ExactOverrideKeyIndex(FrozenSet<string> keys) => _keys = keys;

	/// <summary>Loads the key set from the embedded resource.</summary>
	public static ExactOverrideKeyIndex Load()
	{
		var assembly = typeof(FdcLexicon).Assembly;
		var name = assembly.GetManifestResourceNames().Single(n => n.EndsWith("exact-overrides.json", StringComparison.Ordinal));
		using var stream = assembly.GetManifestResourceStream(name)
			?? throw new InvalidOperationException($"Embedded resource '{name}' not found.");
		using var reader = new StreamReader(stream);
		var keys = JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(reader.ReadToEnd(), JsonOptions)
			?? throw new InvalidOperationException("exact-overrides.json was empty.");
		return new ExactOverrideKeyIndex(keys.Keys.ToFrozenSet(StringComparer.OrdinalIgnoreCase));
	}

	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	/// <summary>Whether the given key is in <c>exact-overrides.json</c> (case-insensitive).</summary>
	/// <param name="key">The candidate key.</param>
	/// <returns><see langword="true"/> when the key is present.</returns>
	public bool Contains(string key) => _keys.Contains(key);
}
