{"content":"using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Runs one census or pairs invocation: reads the trace, refuses any set other than
/// <c>debug</c>/<c>batch</c> (D-029), classifies every <c>auto &amp;&amp; !correct</c> line,
/// writes the TSV to the output sink and the relation × site summary to the error sink.
/// </summary>
public sealed class AutoWrongCensusRunner : IAutoWrongCensusRunner
{
	private readonly AutoWrongCensusOptions _options;
	private readonly AutoWrongClassifier _classifier;
	private readonly FdcNormalizer _normalizer;
	private readonly TextWriter _output;
	private readonly TextWriter _error;

	/// <summary>Creates the runner.</summary>
	/// <param name="options">The bound CLI options.</param>
	/// <param name="classifier">The relation/site classifier.</param>
	/// <param name="normalizer">The production normalizer (pairs head folding).</param>
	/// <param name="output">TSV sink.</param>
	/// <param name="error">Summary/diagnostics sink.</param>
	public AutoWrongCensusRunner(
		AutoWrongCensusOptions options,
		AutoWrongClassifier classifier,
		FdcNormalizer normalizer,
		TextWriter output,
		TextWriter error)
	{
		ArgumentNullException.ThrowIfNull(options);
		ArgumentNullException.ThrowIfNull(classifier);
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(output);
		ArgumentNullException.ThrowIfNull(error);
		_options = options;
		_classifier = classifier;
		_normalizer = normalizer;
		_output = output;
		_error = error;
	}

	/// <summary>Runs the invocation and returns the exit code (0 success, 1 failure).</summary>
	/// <param name="cancellationToken">Cancellation token.</param>
	/// <returns>0 on success; 1 on a missing file, a refused set, or a malformed invocation.</returns>
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		try
		{
			if (string.IsNullOrEmpty(_options.Command))
			{
				AutoWrongCensusUsage.Print();
				return 1;
			}

			if (!File.Exists(_options.TracePath))
			{
				_error.WriteLine($"error: trace file not found at '{_options.TracePath}'.");
				return 1;
			}

			var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
			if (lines is null)
			{
				return 1;
			}

			var refused = lines.FirstOrDefault(l => !l.Set.Equals("debug", StringComparison.OrdinalIgnoreCase)
				&& !l.Set.Equals("batch", StringComparison.OrdinalIgnoreCase));
			if (refused is not null)
			{
				_error.WriteLine($"refused: trace record {refused.HoldoutId}#{refused.LineIndex} has set '{refused.Set}'; only debug and batch traces are classified (D-029).");
				return 1;
			}

			return _options.Command.Equals(CommandLineArgumentParser.PairsCommand, StringComparison.OrdinalIgnoreCase)
				? RunPairs(lines)
				: RunCensus(lines);
		}
		catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
		{
			return 1;
		}
		catch (Exception ex) when (ex is IOException or InvalidOperationException or JsonException)
		{
			_error.WriteLine($"error: {ex.Message}");
			return 1;
		}
	}

	private int RunCensus(IReadOnlyList<TraceLine> lines)
	{
		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		var results = new List<ClassificationResult>(autoWrong.Count);
		var unknownSite = 0;

		foreach (var line in autoWrong)
		{
			var result = _classifier.Classify(line);
			if (string.IsNullOrEmpty(result.Site))
			{
				unknownSite++;
				_error.WriteLine($"error: {line.HoldoutId}#{line.LineIndex} has unknown atom path '{FirstAtomPath(line)}'; cannot determine the site.");
				continue;
			}

			results.Add(result);
		}

		WriteCensusTsv(results);
		WriteCensusSummary(lines.Count, autoWrong.Count, results, unknownSite);

		return unknownSite > 0 ? 1 : 0;
	}

	private int RunPairs(IReadOnlyList<TraceLine> lines)
	{
		if (!File.Exists(_options.CensusTsvPath))
		{
			_error.WriteLine($"error: census TSV not found at '{_options.CensusTsvPath}'.");
			return 1;
		}

		var wanted = ReadWindowRows(_options.CensusTsvPath);
		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		var emitted = 0;

		_output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");
		foreach (var (holdoutId, lineIndex) in wanted)
		{
			if (!byKey.TryGetValue((holdoutId, lineIndex), out var line))
			{
				_error.WriteLine($"warning: census row {holdoutId}#{lineIndex} not found in the trace; skipped.");
				continue;
			}

			var atom = line.Atoms.Count > 0 ? line.Atoms[0] : null;
			var parsedNameHead = atom is null
				? string.Empty
				: string.Join(' ', _classifier.KeyHeadPhrase(_normalizer.NormalizeToTokens(atom.ParsedName)));
			var keyHead = string.Join(' ', _classifier.KeyHeadPhrase(_normalizer.NormalizeToTokens(First(line.ExpectedDescriptions))));
			_output.WriteLine($"{Sanitize(holdoutId)}\t{lineIndex}\t{Sanitize(parsedNameHead)}\t{Sanitize(keyHead)}\t{Sanitize(line.RawText)}");
			emitted++;
		}

		_error.WriteLine($"pairs: {emitted} window compound/other rows emitted from {wanted.Count} wanted.");
		return 0;
	}

	private void WriteCensusTsv(IReadOnlyList<ClassificationResult> results)
	{
		_output.WriteLine("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");
		foreach (var r in results)
		{
			_output.WriteLine(string.Join('\t',
				Sanitize(r.HoldoutId),
				r.LineIndex.ToString(),
				Sanitize(r.Set),
				Sanitize(r.Relation),
				Sanitize(r.Site),
				Sanitize(r.OverrideKey),
				Sanitize(r.AcceptedTier),
				Sanitize(r.KeyTier),
				Sanitize(r.AcceptedState),
				Sanitize(r.KeyState),
				Sanitize(r.ParsedName),
				Sanitize(r.KeyHead),
				Sanitize(r.AcceptedDesc),
				Sanitize(r.KeyDesc),
				Sanitize(r.RawText)));
		}
	}

	private void WriteCensusSummary(int totalLines, int autoWrongCount, IReadOnlyList<ClassificationResult> results, int unknownSite)
	{
		var set = results.Count > 0 ? results[0].Set : string.Empty;
		_error.WriteLine($"autoWrongCensus set={set} traceLines={totalLines} autoWrongLines={autoWrongCount} classified={results.Count}");

		var matrix = results
			.GroupBy(r => (r.Relation, r.Site))
			.OrderBy(g => g.Key.Relation, StringComparer.Ordinal)
			.ThenBy(g => g.Key.Site, StringComparer.Ordinal);
		foreach (var group in matrix)
		{
			_error.WriteLine($"{group.Key.Relation}\t{group.Key.Site}\t{group.Count()}");
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		_error.WriteLine($"relation other: {otherCount}/{autoWrongCount} ({(autoWrongCount > 0 ? otherCount * 100.0 / autoWrongCount : 0.0):0.0}%)");

		var missing = results.Where(r => r.MissingField is not null)
			.GroupBy(r => r.MissingField)
			.Select(g => $"{g.Key}={g.Count()}");
		_error.WriteLine($"missing fields: {(missing.Any() ? string.Join(' ', missing) : "none")}");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		_error.WriteLine($"override-site lines: {overrideLines.Count}, of which {overrideLines.Count(r => r.OverrideKey == "yes")} have the normalized rawText as an exact-overrides.json key");

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		var reuseNameMismatch = reuseLines.Count(r =>
			!string.IsNullOrEmpty(r.ParsedName)
			&& !string.IsNullOrEmpty(r.KeyDesc)
			&& !IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(r.ParsedName), SlugOf(r.KeyDesc)));
		_error.WriteLine($"reuse-site lines: {reuseLines.Count}, of which {reuseLines.Count(r => r.MissingField is null && !string.IsNullOrEmpty(r.ParsedName))} have a parsedName; ShouldReuse(parsedName, key slug) is false for {reuseNameMismatch}");

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		var keyHigher = tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
		_error.WriteLine($"row-choice-tier lines: {tierLines.Count}, key tier higher in {keyHigher}, accepted tier higher in {tierLines.Count - keyHigher}");

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			_error.WriteLine($"same-head-other-qualifier {r.HoldoutId}#{r.LineIndex}: key-only=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] accepted-only=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}

		if (unknownSite > 0)
		{
			_error.WriteLine($"unknown atom paths: {unknownSite}");
		}
	}

	private static string FirstAtomPath(TraceLine line) => line.Atoms.Count > 0 ? line.Atoms[0].Path : string.Empty;

	private static string SlugOf(string description)
	{
		var head = description.Split(',', 2)[0].Trim();
		return IngredientLineParser.ComputeSlug(head);
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srllegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static string Sanitize(string value) =>
		value.Replace('\t', ' ').Replace('\r', ' ').Replace('\n', ' ');

	private static List<(string HoldoutId, int LineIndex)> ReadWindowRows(string censusTsvPath)
	{
		var wanted = new List<(string, int)>();
		var lines = File.ReadLines(censusTsvPath);
		var header = lines.First().Split('\t');
		var idCol = Array.IndexOf(header, "holdoutId");
		var idxCol = Array.IndexOf(header, "lineIndex");
		var blockerCol = Array.IndexOf(header, "blocker");
		var routeCol = Array.IndexOf(header, "route");
		if (idCol < 0 || idxCol < 0 || blockerCol < 0 || routeCol < 0)
		{
			throw new InvalidOperationException($"census TSV '{censusTsvPath}' is missing the holdoutId/lineIndex/blocker/route columns.");
		}

		foreach (var line in lines)
		{
			if (string.IsNullOrWhiteSpace(line))
			{
				continue;
			}

			var cells = line.Split('\t');
			if (cells.Length <= Math.Max(idCol, Math.Max(idxCol, Math.Max(blockerCol, routeCol))))
			{
				continue;
			}

			if (cells[blockerCol].Equals("window", StringComparison.Ordinal)
				&& (cells[routeCol].Equals("compound", StringComparison.Ordinal) || cells[routeCol].Equals("other", StringComparison.Ordinal))
				&& int.TryParse(cells[idxCol], out var lineIndex))
			{
				wanted.Add((cells[idCol], lineIndex));
			}
		}

		return wanted;
	}

	private static async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string path, CancellationToken cancellationToken)
	{
		var options = new System.Text.Json.JsonSerializerOptions(JsonSerializerDefaults.Web);
		var lines = new List<TraceLine>();
		await using var reader = new StreamReader(path);
		string? json;
		while ((json = await reader.ReadLineAsync(cancellationToken).ConfigureAwait(false)) is not null)
		{
			if (string.IsNullOrWhiteSpace(json))
			{
				continue;
			}

			lines.Add(System.Text.Json.JsonSerializer.Deserialize<TraceLine>(json, options)
				?? throw new JsonException($"trace line in '{path}' deserialized to null."));
		}

		return lines;
	}
}
